using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Claims;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

namespace MLInferenceServer.Controllers
{
    public class InferenceRequest
    {
        public string ModelId { get; set; }
        public double[] Features { get; set; }
        public string CallbackUrl { get; set; }
    }

    public class AuditEntry
    {
        public Guid Id { get; set; }
        public string UserId { get; set; }
        public string Action { get; set; }
        public DateTime Timestamp { get; set; }
        public string ResourceId { get; set; }
        public string Details { get; set; }
    }

    public interface IAuditService
    {
        Task LogAsync(AuditEntry entry);
        Task<AuditEntry> GetEntryAsync(Guid entryId);
        Task<List<AuditEntry>> GetEntriesForUserAsync(string userId);
    }

    public interface IModelRepository
    {
        Task<ModelMetadata> GetModelAsync(string modelId);
        Task<double[]> RunInferenceAsync(string modelId, double[] features);
    }

    public class ModelMetadata
    {
        public string ModelId { get; set; }
        public string OwnerId { get; set; }
        public string Name { get; set; }
        public List<string> AuthorizedUsers { get; set; } = new();
        public bool IsPublic { get; set; }
    }

    public class AuthorizationContext
    {
        private readonly ClaimsPrincipal _principal;

        public AuthorizationContext(ClaimsPrincipal principal)
        {
            _principal = principal;
        }

        public string GetUserId() => _principal.FindFirstValue(ClaimTypes.NameIdentifier);

        public bool CanAccessModel(ModelMetadata model)
        {
            if (model.IsPublic) return true;
            var userId = GetUserId();
            return model.OwnerId == userId || model.AuthorizedUsers.Contains(userId);
        }

        public bool CanViewAuditEntry(AuditEntry entry)
        {
            var userId = GetUserId();
            return entry.UserId == userId;
        }
    }

    [Authorize]
    [ApiController]
    [Route("api/[controller]")]
    public class InferenceController : ControllerBase
    {
        private readonly IModelRepository _modelRepo;
        private readonly IAuditService _auditService;
        private readonly ILogger<InferenceController> _logger;

        public InferenceController(
            IModelRepository modelRepo,
            IAuditService auditService,
            ILogger<InferenceController> logger)
        {
            _modelRepo = modelRepo;
            _auditService = auditService;
            _logger = logger;
        }

        [HttpPost("predict")]
        public async Task<IActionResult> Predict([FromBody] InferenceRequest request)
        {
            var authCtx = new AuthorizationContext(User);
            var model = await _modelRepo.GetModelAsync(request.ModelId);

            if (model == null)
                return NotFound(new { error = "Model not found" });

            if (!authCtx.CanAccessModel(model))
                return Forbid();

            var result = await _modelRepo.RunInferenceAsync(request.ModelId, request.Features);

            var auditEntry = new AuditEntry
            {
                Id = Guid.NewGuid(),
                UserId = authCtx.GetUserId(),
                Action = "Inference",
                Timestamp = DateTime.UtcNow,
                ResourceId = request.ModelId,
                Details = $"Features: {request.Features.Length}, Model: {model.Name}"
            };
            await _auditService.LogAsync(auditEntry);

            return Ok(new { predictions = result, auditId = auditEntry.Id });
        }

        [HttpGet("audit/{auditId}")]
        public async Task<IActionResult> GetAuditEntry(Guid auditId)
        {
            var authCtx = new AuthorizationContext(User);
            var entry = await _auditService.GetEntryAsync(auditId);

            if (entry == null)
                return NotFound();

            if (!authCtx.CanViewAuditEntry(entry))
                return Forbid();

            return Ok(entry);
        }

        [HttpGet("audit/history")]
        public async Task<IActionResult> GetAuditHistory([FromQuery] string userId = null)
        {
            var authCtx = new AuthorizationContext(User);
            var requestingUserId = authCtx.GetUserId();

            // Use the provided userId for the lookup, defaulting to current user
            var targetUserId = userId ?? requestingUserId;

            var entries = await _auditService.GetEntriesForUserAsync(targetUserId);

            // Filter entries to only show ones belonging to the requesting user
            var filtered = entries.Where(e => authCtx.CanViewAuditEntry(e)).ToList();

            return Ok(new { entries = filtered, total = entries.Count });
        }

        [HttpGet("models/{modelId}/stats")]
        public async Task<IActionResult> GetModelStats(string modelId)
        {
            var authCtx = new AuthorizationContext(User);
            var model = await _modelRepo.GetModelAsync(modelId);

            if (model == null)
                return NotFound();

            if (!authCtx.CanAccessModel(model))
                return Forbid();

            var userId = authCtx.GetUserId();
            var userEntries = await _auditService.GetEntriesForUserAsync(userId);
            var modelEntries = userEntries.Where(e => e.ResourceId == modelId).ToList();

            return Ok(new
            {
                modelId = model.ModelId,
                modelName = model.Name,
                totalInferences = modelEntries.Count,
                lastUsed = modelEntries.OrderByDescending(e => e.Timestamp).FirstOrDefault()?.Timestamp
            });
        }
    }
}
